using System;using System.Collections.Generic;using System.Reflection;using NUnit.Framework;using Rootborn.Game.Common;using Rootborn.Game.StudentLife;using Rootborn.UI.StudentLife;using UnityEngine;using UnityEngine.UI;using Object=UnityEngine.Object;
namespace Rootborn.Tests.EditMode.UI.StudentLife{public sealed class LocationActivityModalPresentationTests{GameObject canvasGo;LocationIdentityPanel panel;readonly List<Object> owned=new List<Object>();[SetUp]public void SetUp(){canvasGo=new GameObject("LocationModalTestCanvas",typeof(RectTransform),typeof(Canvas));var go=new GameObject("LocationModalOwner");go.transform.SetParent(canvasGo.transform,false);panel=go.AddComponent<LocationIdentityPanel>();}[TearDown]public void TearDown(){Object.DestroyImmediate(canvasGo);foreach(var o in owned)if(o!=null)Object.DestroyImmediate(o);owned.Clear();}
[Test]public void OpenAcquiresWorldInputAndCloseButtonReleasesIt(){Assert.That(UiGameplayInputLock.IsBlocked,Is.False);panel.Show(null,null);Assert.That(UiGameplayInputLock.IsBlocked,Is.True,"A location choice is modal, like the journal and encyclopedia");panel.transform.Find("LocationIdentityRoot/CloseLocation").GetComponent<Button>().onClick.Invoke();Assert.That(UiGameplayInputLock.IsBlocked,Is.False);}
[TestCase(false)][TestCase(true)]public void DisableOrDestroyCannotLeaveWorldInputLocked(bool destroy){panel.Show(null,null);Assert.That(UiGameplayInputLock.IsBlocked,Is.True);if(destroy)Object.DestroyImmediate(panel.gameObject);else panel.gameObject.SetActive(false);Assert.That(UiGameplayInputLock.IsBlocked,Is.False);}
[Test]public void HidingLocationDoesNotReleaseAnotherModalOwner(){var owner=new GameObject("OtherModal");owned.Add(owner);panel.Show(null,null);UiGameplayInputLock.Acquire(owner);panel.Hide();Assert.That(UiGameplayInputLock.IsBlocked,Is.True);UiGameplayInputLock.Release(owner);Assert.That(UiGameplayInputLock.IsBlocked,Is.False);}
[Test]public void PaddedModalHasItsOwnLayerAboveTheHud(){panel.Show(null,null);var root=panel.transform.Find("LocationIdentityRoot").GetComponent<RectTransform>();Assert.That(root.rect.size,Is.EqualTo(new Vector2(1120,800)));var modal=root.GetComponent<Canvas>();Assert.That(modal,Is.Not.Null);Assert.That(modal.overrideSorting,Is.True);Assert.That(modal.sortingOrder,Is.GreaterThan(1000));Assert.That(root.GetComponent<GraphicRaycaster>(),Is.Not.Null);var close=root.Find("CloseLocation").GetComponent<RectTransform>();Assert.That(close.GetComponent<Rootborn.UI.Modern.ModernUiTileImage>(),Is.Not.Null,"Close and activity buttons must use the approved dimensional Comfy molding, not flat color rectangles");Assert.That(root.rect.xMax-(close.anchoredPosition.x+close.rect.width*.5f),Is.GreaterThanOrEqualTo(32));Assert.That(root.rect.yMax-(close.anchoredPosition.y+close.rect.height*.5f),Is.GreaterThanOrEqualTo(32));var viewport=root.GetComponentInChildren<ScrollRect>(true).viewport;Assert.That(viewport.rect.width,Is.GreaterThanOrEqualTo(480));Assert.That(viewport.rect.height,Is.GreaterThanOrEqualTo(260));}
[TestCase(false)][TestCase(true)]public void NamedStateIsInlineRegardlessOfEventSubscriberOrder(bool arrivesFirst){var identity=Identity("test.location");var summary=Summary("test.location",false);if(arrivesFirst)SetSummary(summary);panel.Show(identity,null);if(!arrivesFirst)SetSummary(summary);var text=StateText();Assert.That(text.gameObject.activeSelf,Is.True);Assert.That(text.text,Does.Contain("OPEN STATUS"));Assert.That(text.text,Does.Contain("A useful authored description."));Assert.That(text.text,Does.Not.Contain("state.test"));}
[Test]public void EmptyHiddenAndDifferentLocationNeverLeakRawStateIds(){var identity=Identity("test.location");panel.Show(identity,null);SetSummary(LocationStateSummaryModel.Empty(identity.Location));Assert.That(StateText().gameObject.activeSelf,Is.False);SetSummary(Summary("test.location",true));Assert.That(StateText().gameObject.activeSelf,Is.False);SetSummary(Summary("other.location",false));Assert.That(StateText().gameObject.activeSelf,Is.False);}
[Test]public void SwitchingLocationsClearsPreviouslyResolvedState(){var first=Identity("test.location");panel.Show(first,null);SetSummary(Summary("test.location",false));Assert.That(StateText().gameObject.activeSelf,Is.True);panel.Show(Identity("other.location"),null);Assert.That(StateText().gameObject.activeSelf,Is.False);}
LocationIdentityDefinition Identity(string id){var location=ScriptableObject.CreateInstance<LocationDefinition>();owned.Add(location);location.ConfigureForTests(id,"Location",Vector2.zero,Array.Empty<DiscoveryDefinition>());var identity=ScriptableObject.CreateInstance<LocationIdentityDefinition>();owned.Add(identity);identity.ConfigureForTests(id+".identity","Identity",location,"Description",Array.Empty<LocationActivityDefinition>(),Array.Empty<LocationHintEntry>(),480,1140);return identity;}
LocationStateSummaryModel Summary(string id,bool hidden){var state=ScriptableObject.CreateInstance<LocationStateDefinition>();owned.Add(state);return new LocationStateSummaryModel(id,state,new[]{"state.test"},"OPEN STATUS","A useful authored description.",hidden,Array.Empty<string>(),Array.Empty<string>(),Array.Empty<string>(),Array.Empty<string>(),Array.Empty<string>(),Array.Empty<string>());}
void SetSummary(LocationStateSummaryModel summary){var method=typeof(LocationIdentityPanel).GetMethod("SetLocationStateSummary",BindingFlags.Public|BindingFlags.Instance);Assert.That(method,Is.Not.Null,"Resolved state needs a non-overlapping inline presentation owned by the location panel");method.Invoke(panel,new object[]{summary});}Text StateText(){var t=panel.transform.Find("LocationIdentityRoot/LocationStateSummary");Assert.That(t,Is.Not.Null);return t.GetComponent<Text>();}
}}
